import{_ as t,o as r,c as o,a2 as a}from"./chunks/framework.CdvW4CUT.js";const m=JSON.parse('{"title":"Documentation source revisions","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://cx-pl.io/project/revisions.html"}],["meta",{"property":"og:url","content":"https://cx-pl.io/project/revisions.html"}]]},"headers":[],"relativePath":"project/revisions.md","filePath":"project/revisions.md","lastUpdated":null}'),d={name:"project/revisions.md"};function n(s,e,i,c,p,l){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="documentation-source-revisions" tabindex="-1">Documentation source revisions <a class="header-anchor" href="#documentation-source-revisions" aria-label="Permalink to &quot;Documentation source revisions&quot;">​</a></h1><p>The imported reference pages are generated from committed repository snapshots. Local repositories contained uncommitted changes when this site was created; the import uses committed files only. Review and advance these pins when refreshing documentation. These SHAs identify development snapshots, not a released CX version.</p><h2 id="verification-performed" tabindex="-1">Verification performed <a class="header-anchor" href="#verification-performed" aria-label="Permalink to &quot;Verification performed&quot;">​</a></h2><p>On Windows x64, the pinned compiler and runtime were used to build and run the Hello World, arrays and loops, and Counter programs. The compiler build completed with no warnings or errors. Hello World printed <code>Hello world!</code>; the arrays sample printed <code>arrays pass</code>; Counter printed <code>objects pass</code>. The older classes sample in the examples repository did not compile against this compiler snapshot, so the tutorial uses its own verified Counter program instead.</p><p>The Linux workflow is described from the runtime repository&#39;s development documentation but was not run as part of this site build. The package manager and editor extension revisions below are provenance pins only; their workflows have not been verified here.</p><table tabindex="0"><thead><tr><th>Repository</th><th>Revision</th><th>Imported content</th></tr></thead><tbody><tr><td><a href="https://github.com/cx-pl/cxc/tree/f24e1cb637b5952178d0b89f39613512a2f4b417" target="_blank" rel="noreferrer">cxc</a></td><td><code>f24e1cb637b5952178d0b89f39613512a2f4b417</code></td><td>Language reference</td></tr><tr><td><a href="https://github.com/cx-pl/cxcore/tree/26b4868617f19db79686292d1b85315b20f8e160" target="_blank" rel="noreferrer">cxcore</a></td><td><code>26b4868617f19db79686292d1b85315b20f8e160</code></td><td>Runtime contracts and ABI</td></tr><tr><td><a href="https://github.com/cx-pl/examples/tree/885d33246864e32c7de53b20401d43fddeb9f5e0" target="_blank" rel="noreferrer">examples</a></td><td><code>885d33246864e32c7de53b20401d43fddeb9f5e0</code></td><td>Tutorial samples</td></tr><tr><td><a href="https://github.com/cx-pl/cxpm/tree/c47d720a30fb9a499509bbd439f4989a2f0e90ed" target="_blank" rel="noreferrer">cxpm</a></td><td><code>c47d720a30fb9a499509bbd439f4989a2f0e90ed</code></td><td>Package manager guide</td></tr><tr><td><a href="https://github.com/cx-pl/vscode-extension/tree/7b2eb4ac41fec5bdf34a0aeb3f6779940180b4d1" target="_blank" rel="noreferrer">vscode-extension</a></td><td><code>7b2eb4ac41fec5bdf34a0aeb3f6779940180b4d1</code></td><td>Editor setup and syntax grammar</td></tr></tbody></table><p>Use <code>pnpm content:sync</code> to regenerate the committed reference snapshots and imported examples from these exact commits. Edit <code>content-sources.json</code> to advance the pins; review resulting changes and verify the tutorial instructions before merging.</p>',7)])])}const f=t(d,[["render",n]]);export{m as __pageData,f as default};
